HOWTO_KANNADA_ROWS: dict[str, tuple[str, ...]] = {
    "kn": (
        "Go and Help ಬಳಸುವ ವಿಧಾನ",
        "ಪ್ರಯಾಣಿಕರು, ಸ್ಥಳೀಯರು ಮತ್ತು ಇವರ ನಡುವೆ ಇರುವ ಎಲ್ಲರಿಗಾಗಿ ಸಂಕ್ಷಿಪ್ತ ಮಾರ್ಗದರ್ಶಿ.",
        "1 ಜೂನ್ 2024ರಂದು ನವೀಕರಿಸಲಾಗಿದೆ ಮತ್ತು ಜಾರಿಗೆ ಬಂದಿದೆ",
        "Go and Help ಜನರನ್ನು ಸಂಪರ್ಕಿಸುತ್ತದೆ. ಇದು ಯಾರನ್ನೂ ನೇಮಿಸಿಕೊಳ್ಳುವುದಿಲ್ಲ, ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡುವುದಿಲ್ಲ, ತರಬೇತಿ ನೀಡುವುದಿಲ್ಲ ಅಥವಾ ಪರಿಶೀಲಿಸುವುದಿಲ್ಲ. ಪ್ರತಿಯೊಂದು ಭೇಟಿ, ಪ್ರಯಾಣ ಮತ್ತು ಕೆಲಸವನ್ನು ತಮ್ಮ ನಿರ್ಧಾರವನ್ನು ತಾವೇ ತೆಗೆದುಕೊಳ್ಳುವ ವಯಸ್ಕರು ಪರಸ್ಪರ ಏರ್ಪಡಿಸುತ್ತಾರೆ; ಯಾರನ್ನಾದರೂ ಭೇಟಿಯಾಗಲು ಒಪ್ಪುವ ಮೊದಲು ಈ ಪುಟವನ್ನು ಓದಿ.",
        "ನಕ್ಷೆ ಮತ್ತು ಅದನ್ನು ನೋಡುವ ಎರಡು ವಿಧಾನಗಳು",
        "ನಕ್ಷೆಯೇ ಅಪ್ಲಿಕೇಶನ್‌ನ ಹೃದಯವಾಗಿರುವುದರಿಂದ ಅದು ಪರದೆಯನ್ನೆಲ್ಲ ತುಂಬುತ್ತದೆ. ಅಕ್ಕಪಕ್ಕದಲ್ಲಿ ಎರಡು ವಿಧಾನಗಳಿವೆ. Give ನಲ್ಲಿ ಸಹಾಯ ಕೇಳುತ್ತಿರುವವರು ಕಾಣಿಸುತ್ತಾರೆ: ಪ್ರತಿಯೊಂದು ಗುರುತು ನೀವು ಸ್ವೀಕರಿಸಬಹುದಾದ ತೆರೆದ ವಿನಂತಿಯಾಗಿದೆ. Get ನಲ್ಲಿ ಸಹಾಯ ನೀಡಲು ಸಿದ್ಧರಾಗಿರುವ ಸದಸ್ಯರು ಕಾಣಿಸುತ್ತಾರೆ; ಅವರ ಪ್ರೊಫೈಲ್ ಓದಿ, ನಂತರ ಅವರು ಸ್ವೀಕರಿಸಬಹುದಾದ ವಿನಂತಿಯನ್ನು ಪ್ರಕಟಿಸಬಹುದು.",
        "ಹಿಗ್ಗಿಸಲು ಅಥವಾ ಕುಗ್ಗಿಸಲು ಎರಡು ಬೆರಳುಗಳಿಂದ ಪಿಂಚ್ ಮಾಡಿ, ಒಂದು ಬೆರಳಿನಿಂದ ಎಳೆದು ನಕ್ಷೆಯನ್ನು ಸರಿಸಿ, ಎರಡು ಬೆರಳುಗಳಿಂದ ತಿರುಗಿಸಿ. ನಕ್ಷೆ ಉತ್ತರ ದಿಕ್ಕಿನಿಂದ ಬೇರೆ ದಿಕ್ಕಿಗೆ ತಿರುಗಿದಾಗ, ನಕ್ಷೆ ಮತ್ತು ಪಟ್ಟಿ ಬದಲಿಸುವ ನಿಯಂತ್ರಣದ ಬಳಿ ಸಣ್ಣ ದಿಕ್ಸೂಚಿ ಕಾಣಿಸುತ್ತದೆ. ಅದನ್ನು ಒಮ್ಮೆ ಒತ್ತಿದರೆ ನಕ್ಷೆ ಮತ್ತೆ ಉತ್ತರದ ಕಡೆಗೆ ಬರುತ್ತದೆ.",
        "ನಕ್ಷೆ ತುಂಬಾ ಗಿಜಿಗುಡಿದಂತೆ ಕಂಡಾಗ ಪಟ್ಟಿಯ ನೋಟಕ್ಕೆ ಬದಲಾಯಿಸಿ. ನಕ್ಷೆಯಲ್ಲಿ ಒಂದೇ ವ್ಯಕ್ತಿಯ ಹಲವು ವಿನಂತಿಗಳನ್ನು ಒಂದು ಪ್ರೊಫೈಲ್ ಗುರುತಿನ ಹಿಂದೆ ಒಟ್ಟುಗೂಡಿಸಿದ್ದರೂ, ಪಟ್ಟಿಯಲ್ಲಿ ಪ್ರತಿಯೊಂದು ವಿನಂತಿಯೂ ಪ್ರತ್ಯೇಕವಾಗಿ ಕಾಣಿಸುತ್ತದೆ. ಒಟ್ಟುಗೂಡಿಸಿದ ಗುರುತನ್ನು ಒತ್ತಿದರೆ ಆ ವ್ಯಕ್ತಿಯ ವಿನಂತಿಗಳನ್ನು ಒಂದೊಂದಾಗಿ ನೋಡಬಹುದು.",
        "ನಿಮ್ಮ ಸ್ಥಳದ ಬಗ್ಗೆ ಏನನ್ನು ಹಂಚಿಕೊಳ್ಳಬೇಕೆಂದು ಆಯ್ಕೆಮಾಡುವುದು",
        "Set my location ನಲ್ಲಿ ಮೂರು ಆಯ್ಕೆಗಳಿವೆ; ಅವುಗಳ ನಡುವೆ ಬೇರೆ ಆಯ್ಕೆ ಇಲ್ಲ. Off ಮಾಡಿದರೆ ನೀವು ಯಾವುದೇ ನಕ್ಷೆಯಲ್ಲಿ ಅಥವಾ ಜನರ ಹುಡುಕಾಟದಲ್ಲಿ ಕಾಣಿಸುವುದಿಲ್ಲ. ಉಳಿಸಿದ ನಿರ್ದೇಶಾಂಕಗಳು ನಿಮ್ಮ ಖಾತೆಯಲ್ಲಿ ಖಾಸಗಿಯಾಗಿ ಉಳಿಯುತ್ತವೆ, ಆದರೆ ಯಾವುದೇ ನಿರ್ದೇಶಾಂಕವನ್ನು ಎಲ್ಲಿಗೂ ಕಳುಹಿಸುವುದಿಲ್ಲ. Approximate ನಿಮ್ಮ ನಿಖರ ಸ್ಥಳವನ್ನು ಖಾಸಗಿಯಾಗಿರಿಸಿ, 500m ಮತ್ತು 1km ನಡುವಿನ ದೂರದಲ್ಲಿರುವ ನೆಲಸುರಕ್ಷಿತ ಬಿಂದುವನ್ನು ಮಾತ್ರ ಎಲ್ಲ ಬಳಕೆದಾರರಿಗೆ ಪ್ರಕಟಿಸುತ್ತದೆ. Live ನಿಮ್ಮ ನಿಖರ ಸ್ಥಳವನ್ನು ಎಲ್ಲ ಬಳಕೆದಾರರಿಗೆ ಪ್ರಕಟಿಸುತ್ತದೆ; Refresh my position ಒತ್ತಿದಾಗ ಮಾತ್ರ ಅದನ್ನು ನವೀಕರಿಸಲಾಗುತ್ತದೆ.",
        "ಇದನ್ನು ಸ್ಪಷ್ಟವಾಗಿ ಗಮನಿಸಿ: Live ವಿಧಾನದಲ್ಲಿ ಎಲ್ಲ ಬಳಕೆದಾರರೂ ನಕ್ಷೆಯಲ್ಲಿ ನಿಮ್ಮ ನಿಖರ ಬಿಂದುವನ್ನು ನೋಡಬಹುದು; ಅದು ಅಂದಾಜಿನ ವೃತ್ತವಲ್ಲ. ಅಪರಿಚಿತರು ನಿಮ್ಮ ಮನೆಯ ಹೊರಗೆ ನಿಲ್ಲುವುದು ನಿಮಗೆ ಬೇಡವೆಂದರೆ, ಮನೆಯ ವಿಳಾಸದಲ್ಲಿ Live ಬಳಸಬೇಡಿ. Approximate ಅಥವಾ ಹತ್ತಿರದ ಚೌಕ, ಮಾರುಕಟ್ಟೆ ಅಥವಾ ಕೆಫೆಯನ್ನು ಆಯ್ಕೆಮಾಡುವುದು ಸಾಮಾನ್ಯವಾಗಿ ಉತ್ತಮ.",
        "Live ಸ್ಥಳವು ನಿಮ್ಮ ಬ್ರೌಸರ್ ಮತ್ತು ಸಾಧನವನ್ನು ಅವಲಂಬಿಸಿದೆ. ಹೆಚ್ಚಿನ ಬ್ರೌಸರ್‌ಗಳು ಸುರಕ್ಷಿತ https:// ವಿಳಾಸದಲ್ಲಷ್ಟೇ ಇದನ್ನು ಒದಗಿಸುತ್ತವೆ ಮತ್ತು ಎಲ್ಲ ಬ್ರೌಸರ್‌ಗಳೂ ಮೊದಲು ನಿಮ್ಮ ಅನುಮತಿ ಕೇಳುತ್ತವೆ. ನೀವು ನಿರಾಕರಿಸಿದರೆ ಅಥವಾ ಸಂಕೇತ ದುರ್ಬಲವಾಗಿದ್ದರೆ, ಅಪ್ಲಿಕೇಶನ್ ನಿಮಗೆ ತಿಳಿಸುತ್ತದೆ ಮತ್ತು ಏನನ್ನೂ ಉಳಿಸುವುದಿಲ್ಲ. ಸೈನ್ ಇನ್ ಆಗದವರಿಗೆ ಸದಸ್ಯರ ಯಾವುದೇ ನಿರ್ದೇಶಾಂಕಗಳನ್ನು ನೀಡುವುದಿಲ್ಲ.",
        "ಸಹಾಯ ವಿನಂತಿಯನ್ನು ಪ್ರಕಟಿಸುವುದು",
        "ವಿಷಯವನ್ನು ಸರಳವಾಗಿ ಬರೆಯಿರಿ. ಕೆಲಸವೇನು, ಸುಮಾರು ಎಷ್ಟು ಸಮಯ ಬೇಕು, ಯಾವ ಉಪಕರಣ ಅಥವಾ ಕೌಶಲ್ಯ ಅಗತ್ಯ, ನಿಮಗೆ ಯಾವಾಗ ಸಮಯವಿದೆ ಮತ್ತು ಪ್ರತಿಯಾಗಿ ಏನು ನೀಡುತ್ತೀರಿ—ಊಟ, ಒಂದು ರಾತ್ರಿ ವಸತಿ, ಮಾರ್ಗದರ್ಶಿತ ನಡಿಗೆ, ಪಾಠ ಅಥವಾ ಸರಳ ಧನ್ಯವಾದ—ಎಂದು ತಿಳಿಸಿ. ಛಾಯಾಚಿತ್ರಗಳು ಬಹಳ ಸಹಾಯಕ: ಬೇಲಿ, ಗೋಡೆ ಅಥವಾ ಅಡುಗೆಮನೆಯ ಒಂದು ಚಿತ್ರವೇ ಹನ್ನೆರಡು ಸಂದೇಶಗಳನ್ನು ಉಳಿಸಬಹುದು.",
        "ಉಚಿತ ಸದಸ್ಯತ್ವದಲ್ಲಿ ಒಂದೇ ಸಮಯದಲ್ಲಿ ಕೆಲವೇ ವಿನಂತಿಗಳನ್ನು ತೆರೆದಿಡಬಹುದು; ನಕ್ಷೆಯ ಮಾಹಿತಿ ನಿಖರವಾಗಿರಲು ಪ್ರತಿ ವಿನಂತಿಯೂ ಸ್ವಲ್ಪ ಸಮಯದ ಬಳಿಕ ಅವಧಿ ಮುಗಿಯುತ್ತದೆ. ಪ್ರೀಮಿಯಂ ಸದಸ್ಯತ್ವದಲ್ಲಿ ಒಂದೇ ಸಮಯದಲ್ಲಿ 10 ವಿನಂತಿಗಳವರೆಗೆ ಇರಿಸಬಹುದು. ಯಾರೂ ವ್ಯರ್ಥವಾಗಿ ಪ್ರಯಾಣಿಸದಂತೆ ಕೆಲಸವಾದ ಕೂಡಲೇ ವಿನಂತಿಯನ್ನು ಮುಚ್ಚಿ ಅಥವಾ ಪೂರ್ಣಗೊಳಿಸಿ.",
        "ಕಾನೂನುಬಾಹಿರ, ಅಪಾಯಕಾರಿ, ಲೈಂಗಿಕ ಸ್ವರೂಪದ ಅಥವಾ ನೀವು ಸ್ವತಃ ಒಪ್ಪದ ಪರಿಸ್ಥಿತಿಯಲ್ಲಿ ಯಾರನ್ನಾದರೂ ಕೆಲಸ ಮಾಡಲು ಕೇಳುವ ವಿಷಯವನ್ನು ಎಂದಿಗೂ ಪ್ರಕಟಿಸಬೇಡಿ. ಹಣ ವರ್ಗಾವಣೆ, ಠೇವಣಿ, ದಾಖಲೆಗಳು ಅಥವಾ ಖಾತೆಯ ವಿವರಗಳನ್ನು ಕೇಳಬೇಡಿ.",
        "ವಿನಂತಿ ಸ್ವೀಕರಿಸುವುದು ಮತ್ತು ಸುರಕ್ಷಿತವಾಗಿ ಭೇಟಿಯಾಗುವುದು",
        "ವಿನಂತಿಯನ್ನು ಸ್ವೀಕರಿಸಿದಾಗ ಅದನ್ನು ಪ್ರಕಟಿಸಿದ ವ್ಯಕ್ತಿಯೊಂದಿಗೆ ಸಂಭಾಷಣೆ ತೆರೆಯುತ್ತದೆ. ಅಲ್ಲಿ ನಿಖರ ಭೇಟಿ ಸ್ಥಳ, ಸಮಯ, ಏನು ತರಬೇಕು ಮತ್ತು ಪ್ರತಿಫಲವೇನು ಎಂಬ ವಿವರಗಳನ್ನು ಒಪ್ಪಿಕೊಳ್ಳಿ. ಇಬ್ಬರಿಗೂ ಒಂದೇ ವಿವರಗಳು ಇರಲೆಂದು ಅವನ್ನು ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲೇ ಬರೆಯಿರಿ.",
        "ಮೊದಲು ಸಾರ್ವಜನಿಕ ಸ್ಥಳದಲ್ಲಿ ಭೇಟಿಯಾಗಿ. ನೀವು ಎಲ್ಲಿಗೆ ಹೋಗುತ್ತೀರಿ ಮತ್ತು ಯಾವಾಗ ಹಿಂದಿರುಗುತ್ತೀರಿ ಎಂದು ನಂಬಿಕೆಯ ವ್ಯಕ್ತಿಗೆ ತಿಳಿಸಿ. ಫೋನ್ ಚಾರ್ಜ್ ಆಗಿರಲಿ. ಪಾಸ್‌ಪೋರ್ಟ್, ಕೀಲಿಗಳು ಅಥವಾ ಬ್ಯಾಂಕ್ ವಿವರಗಳನ್ನು ಯಾರಿಗೂ ಕೊಡಬೇಡಿ. ಕೆಲಸವು ವಿವರಣೆಯಂತಿಲ್ಲದಿದ್ದರೆ ಅಥವಾ ಏನಾದರೂ ಸರಿಯಿಲ್ಲವೆನಿಸಿದರೆ, ನಿಲ್ಲಿಸಿ ಅಲ್ಲಿಂದ ಹೊರಡಿ—ಮುಂದುವರಿಯುವ ಬಾಧ್ಯತೆ ನಿಮಗಿಲ್ಲ.",
        "ದೈಹಿಕ, ವಿದ್ಯುತ್, ಕಟ್ಟಡದ ರಚನೆಗೆ ಸಂಬಂಧಿಸಿದ, ವೈದ್ಯಕೀಯ ಅಥವಾ ಮಕ್ಕಳ ಆರೈಕೆಯ ಕೆಲಸ ಮಾಡುವ ಮೊದಲು ವಿಮೆ, ಪರವಾನಗಿಗಳು ಮತ್ತು ಸ್ಥಳೀಯ ನಿಯಮಗಳನ್ನು ಪರಿಗಣಿಸಿ. ಕೆಲವು ದೇಶಗಳಲ್ಲಿ ಕೆಲವು ಕೆಲಸಗಳಿಗೆ ಪರವಾನಗಿ ಪಡೆದ ವ್ಯಕ್ತಿ ಬೇಕಾಗಬಹುದು; ಈ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿನ ಯಾವುದೇ ಪ್ರಕಟಣೆ ಅದನ್ನು ಬದಲಾಯಿಸುವುದಿಲ್ಲ.",
        "ಸಂದೇಶಗಳು, ಸಂಪರ್ಕಗಳು ಮತ್ತು ವೇದಿಕೆ",
        "ಕೆಲಸದ ಸಂಭಾಷಣೆಗಳು ನಿರ್ದಿಷ್ಟ ವಿನಂತಿಗೆ ಸೇರಿರುತ್ತವೆ. ಸಂಪರ್ಕ ವಿನಂತಿಗಳು ಪ್ರತ್ಯೇಕವಾಗಿವೆ: ಇಬ್ಬರೂ ಪರಸ್ಪರ ಒಪ್ಪಿಕೊಂಡ ಬಳಿಕ ಅವರ ನಡುವೆ ನೇರ ಸಂದೇಶದ ಸಂಭಾಷಣೆ ತೆರೆಯೇ ಇರುತ್ತದೆ.",
        "ಸಮುದಾಯ ವೇದಿಕೆ ದೀರ್ಘ ಚರ್ಚೆಗಳ ಸ್ಥಳ—ಪ್ರಶ್ನೆಗಳು, ಕಥೆಗಳು, ಮಾರ್ಗ ಸಲಹೆಗಳು ಮತ್ತು ಅನುಭವದಿಂದ ಪಡೆದ ಪ್ರಾಯೋಗಿಕ ಜ್ಞಾನಕ್ಕೆ. ಓದುವುದು ಉಚಿತ. ವಿಷಯಗಳು ಮತ್ತು ಪ್ರತಿಕ್ರಿಯೆಗಳನ್ನು ಬರೆಯುವುದು ಪ್ರೀಮಿಯಂ ಸದಸ್ಯತ್ವದ ಭಾಗವಾಗಿದೆ.",
        "ಸಾಧ್ಯವಾದಷ್ಟು ಕಾಲ ಸಂಭಾಷಣೆಗಳನ್ನು ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲೇ ಇರಿಸಿ. ಇದರಿಂದ ದಾಖಲೆಯೊಂದು ಉಳಿಯುತ್ತದೆ ಮತ್ತು ಇನ್ನೂ ಭೇಟಿಯಾಗದ ವ್ಯಕ್ತಿಗೆ ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಫೋನ್ ಸಂಖ್ಯೆ ಅಥವಾ ಇಮೇಲ್ ನೀಡಬೇಕಾಗುವುದಿಲ್ಲ.",
        "ಸದಸ್ಯತ್ವ",
        "ಸಹಾಯ ನೀಡುವುದು ಮತ್ತು ಒದಗಿಸುವುದು ಯಾವಾಗಲೂ ಉಚಿತ. ಸದಸ್ಯತ್ವವು ಯೋಜನೆಯನ್ನು ಮುಂದುವರಿಸಲು ನೀಡುವ ಕೊಡುಗೆಯಾಗಿದ್ದು, ವೇದಿಕೆ, ಒಂದೇ ಸಮಯದಲ್ಲಿ 10 ವಿನಂತಿಗಳು, ಆದ್ಯತೆಯ ಸ್ಥಾನ, ಸುಧಾರಿತ ಹುಡುಕಾಟ ಆಯ್ಕೆಗಳು ಮತ್ತು ಹೆಚ್ಚುವರಿ ಪ್ರದರ್ಶನ ಆಯ್ಕೆಗಳನ್ನು ಒದಗಿಸುತ್ತದೆ.",
        "ಎರಡು ಆಯ್ಕೆಗಳಿವೆ—ಮಾಸಿಕ ಟಿಕೆಟ್ ಮತ್ತು ವಾರ್ಷಿಕ ಪಾಸ್—ಮತ್ತು ಎರಡೂ ಒಂದೇ ಪ್ರಯೋಜನಗಳನ್ನು ನೀಡುತ್ತವೆ. ಪಾವತಿಯನ್ನು Stripe ನಿರ್ವಹಿಸುತ್ತದೆ; ಅಪ್ಲಿಕೇಶನ್ ನಿಮ್ಮ ಕಾರ್ಡ್ ವಿವರಗಳನ್ನು ನೋಡುವುದಿಲ್ಲ ಅಥವಾ ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ. ನಿಮ್ಮ ಪ್ರೊಫೈಲ್‌ನ ಬಿಲ್ಲಿಂಗ್ ಪೋರ್ಟಲ್‌ನಿಂದ ಯಾವಾಗ ಬೇಕಾದರೂ ರದ್ದುಮಾಡಬಹುದು.",
        "ವಿಮರ್ಶೆಗಳು",
        "ಕೆಲಸ ಪೂರ್ಣಗೊಂಡ ಬಳಿಕ ವಿನಂತಿ ಪ್ರಕಟಿಸಿದವರು ಮತ್ತು ಸಹಾಯ ಮಾಡಿದವರು ಇಬ್ಬರೂ ಸಮಯಪಾಲನೆ, ಕೆಲಸದ ನಿಷ್ಠೆ, ಕೌಶಲ್ಯ ಮತ್ತು ಸ್ನೇಹಪರತೆ ಎಂಬ ನಾಲ್ಕು ಅಂಶಗಳಲ್ಲಿ ಪರಸ್ಪರ ವಿಮರ್ಶಿಸಬಹುದು. ಈ ನಾಲ್ಕರ ಸರಾಸರಿಯೇ ಪ್ರೊಫೈಲ್‌ನಲ್ಲಿ ಕಾಣುವ ಒಟ್ಟು ನಕ್ಷತ್ರ ಮೌಲ್ಯಮಾಪನವಾಗುತ್ತದೆ.",
        "ನೀವೇ ಓದಲು ಬಯಸುವ ರೀತಿಯಲ್ಲಿ ವಿಮರ್ಶೆ ಬರೆಯಿರಿ: ನಿರ್ದಿಷ್ಟವಾಗಿ, ನ್ಯಾಯಯುತವಾಗಿ ಮತ್ತು ವೈಯಕ್ತಿಕ ವಿವರಗಳಿಲ್ಲದೆ. ವಿಮರ್ಶೆಯು ನಿಮ್ಮ ನೈಜ ಅನುಭವವಾಗಿರಲಿ; ಆಯುಧವಾಗಲಿ ಅಥವಾ ಉಪಕಾರದ ಪ್ರತಿಯಾಗಿ ಬರೆಯುವುದಾಗಲಿ ಬೇಡ.",
        "ವರದಿ ಮತ್ತು ಸುರಕ್ಷತೆ",
        "ಯಾರಾದರೂ ಅಪಾಯಕಾರಿಯಾಗಿ, ಅಪ್ರಾಮಾಣಿಕವಾಗಿ ಅಥವಾ ನಿಂದನಾತ್ಮಕವಾಗಿ ವರ್ತಿಸಿದರೆ, ಸಂಭಾಷಣೆಯನ್ನು ನಿಲ್ಲಿಸಿ ಅವರ ಪ್ರೊಫೈಲ್ ಅಥವಾ ಸಂಭಾಷಣೆಯಿಂದ ವರದಿ ಮಾಡಿ. ಸಂದೇಶಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳಿ—ಅವು ದಾಖಲೆಯಾಗಿರುತ್ತವೆ.",
        "ತುರ್ತು ಪರಿಸ್ಥಿತಿಯಲ್ಲಿ ಮೊದಲು ನಿಮ್ಮ ಸ್ಥಳೀಯ ತುರ್ತು ಸೇವೆಗಳನ್ನು ಸಂಪರ್ಕಿಸಿ. Go and Help ತುರ್ತು ಸೇವೆಯಲ್ಲ ಮತ್ತು ಸ್ಥಳದಲ್ಲೇ ಮಧ್ಯಪ್ರವೇಶಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ನಾವು ಖಾತೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ವಿಷಯ ಅಥವಾ ಪ್ರವೇಶವನ್ನು ತೆಗೆದುಹಾಕಬಹುದು, ಆದರೆ ಈಗಾಗಲೇ ಸಂಭವಿಸಿದುದನ್ನು ಹಿಂತಿರುಗಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
        "ಸುರಕ್ಷತಾ ಮುನ್ನೆಚ್ಚರಿಕೆಗಳು — ಯಾರನ್ನಾದರೂ ಭೇಟಿಯಾಗುವ ಮೊದಲು ಇದನ್ನು ಓದಿ",
        "Go and Help ಜನರನ್ನು ಪರಿಚಯಿಸುವ ಸಾಧನ ಮಾತ್ರ. ನಾವು ಯಾವುದೇ ಭೇಟಿಯನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡುವುದಿಲ್ಲ, ಜೊತೆಯಲ್ಲಿ ಇರುವುದಿಲ್ಲ ಅಥವಾ ಹಾಜರಾಗುವುದಿಲ್ಲ; ಯಾರ ಗುರುತಿನ ದಾಖಲೆ, ಅಪರಾಧ ದಾಖಲೆ, ವಿಮೆ, ಚಾಲನಾ ಪರವಾನಗಿ ಅಥವಾ ವೃತ್ತಿಪರ ಅರ್ಹತೆಯನ್ನು ಪರಿಶೀಲಿಸುವುದಿಲ್ಲ. ನಕ್ಷತ್ರ ಮೌಲ್ಯಮಾಪನಗಳು ಇತರ ಸದಸ್ಯರ ಅಭಿಪ್ರಾಯಗಳಷ್ಟೇ—ಸುರಕ್ಷತೆ, ಪ್ರಾಮಾಣಿಕತೆ ಅಥವಾ ಸಾಮರ್ಥ್ಯದ ಖಾತರಿಯಲ್ಲ. ನಿಮ್ಮ ಸ್ವಂತ ವಿವೇಚನೆಯೇ ನಿಮ್ಮ ನಿಜವಾದ ರಕ್ಷಣೆ.",
        "ನೀವು ಹಂಚಿಕೊಳ್ಳಬಹುದಾದ ಅತ್ಯಂತ ಸೂಕ್ಷ್ಮ ಮಾಹಿತಿ ನಿಮ್ಮ ನಿಖರ ಸ್ಥಳ",
        "Live ನಿಮ್ಮ ನಿಖರ ಅಕ್ಷಾಂಶ ಮತ್ತು ರೇಖಾಂಶವನ್ನು ಎಲ್ಲ ಬಳಕೆದಾರರಿಗೆ ಪ್ರಕಟಿಸುತ್ತದೆ—ಅಂದಾಜಿನ ವೃತ್ತವನ್ನಾಗಲಿ, ನೆರೆಹೊರೆಯ ಪ್ರದೇಶವನ್ನಾಗಲಿ ಅಲ್ಲ. ಆ ನಿರ್ದೇಶಾಂಕ ನಿಮ್ಮ ಹಾಸಿಗೆ, ಹಾಸ್ಟೆಲ್‌ನ ಹಂಚಿಕೆಯ ಕೊಠಡಿ, ನಿಲ್ಲಿಸಿದ ವ್ಯಾನ್ ಅಥವಾ ಮನೆಯ ಬಾಗಿಲನ್ನು ತೋರಿಸಿದರೆ, ಅಪರಿಚಿತರಿಗೆ ನೀವು ಎಲ್ಲಿ ಮಲಗುತ್ತೀರಿ ಎಂದು ತಿಳಿಸಿದಂತಾಗುತ್ತದೆ. ಯಾವುದನ್ನಾದರೂ ಸಕ್ರಿಯಗೊಳಿಸುವ ಮೊದಲು ಇದನ್ನು ಯೋಚಿಸಿ.",
        "ಬದಲಿಗೆ ಸುರಕ್ಷಿತವಾದ ಸಾರ್ವಜನಿಕ ಸ್ಥಿರ ಸ್ಥಳವನ್ನು ಆರಿಸಿ: ಮುಖ್ಯ ಚೌಕ, ಸಾರಿಗೆ ಕೇಂದ್ರ, ಜನನಿಬಿಡ ಕೆಫೆಯ ಹೊರಾಂಗಣ ಆಸನ, ಗ್ರಂಥಾಲಯ ಅಥವಾ ಮಾರುಕಟ್ಟೆಯ ಪ್ರವೇಶದ್ವಾರ. ನೀವು ನಿಜವಾಗಿ ತಂಗಿರುವ ಸ್ಥಳದಿಂದ ಕೆಲವು ನಿಮಿಷಗಳ ದೂರದಲ್ಲಿದ್ದು, ಭೇಟಿಯಾಗುವ ಸಮಯದಲ್ಲಿ ಜನರಿರುವ ಸ್ಥಳವಾಗಿರಲಿ. ಅಂತಹ ಸ್ಥಿರ ಸ್ಥಳವು ನಿಮ್ಮ ವಿಳಾಸವನ್ನು ನೀಡದೆ, ‘ನಾನು ಸುಮಾರು ಇಲ್ಲಿದ್ದೇನೆ ಮತ್ತು ಇಲ್ಲಿ ಭೇಟಿಯಾಗಬಹುದು’ ಎಂದು ತಿಳಿಸುತ್ತದೆ.",
        "ನಿಮಗೆ ನಿಜವಾಗಿಯೂ ಅಗತ್ಯವಿರುವಾಗ ಮಾತ್ರ Live ಸ್ಥಳವನ್ನು ಬಳಸಿ—ಉದಾಹರಣೆಗೆ, ಈಗಾಗಲೇ ಒಪ್ಪಿಕೊಂಡ ಕೆಲಸದ ವೇಳೆ ಸಹಾಯಕರು ನಿಮ್ಮತ್ತ ನಡೆದು ಬರುತ್ತಿರುವಾಗ. ಕೆಲಸ ಮುಗಿದ ಕೂಡಲೇ Hidden ಅಥವಾ ಸಾರ್ವಜನಿಕ ಸ್ಥಿರ ಸ್ಥಳಕ್ಕೆ ಬದಲಾಯಿಸಿ. ಆನ್ ಮಾಡಿದ Live ಹಂಚಿಕೆಯನ್ನು ಮರೆತುಬಿಡುವುದು ನಿಮ್ಮ ಮನೆವರೆಗೆ ಯಾರಾದರೂ ಹಿಂಬಾಲಿಸಲು ಸುಲಭವಾದ ಮಾರ್ಗವಾಗಿದೆ.",
        "Hidden ನಿಮ್ಮನ್ನು ಸದಸ್ಯರ ನಕ್ಷೆ ಮತ್ತು ಸದಸ್ಯರ ಹುಡುಕಾಟದಿಂದ ಸಂಪೂರ್ಣವಾಗಿ ತೆಗೆದುಹಾಕುತ್ತದೆ. ಆದರೂ ನೀವು ಬರೆಯಬಹುದು, ಓದಬಹುದು, ಸಹಾಯ ನೀಡಬಹುದು ಮತ್ತು ಸಂದೇಶಗಳಿಗೆ ಉತ್ತರಿಸಬಹುದು. ಒಬ್ಬರೇ ಪ್ರಯಾಣಿಸುತ್ತಿದ್ದರೆ, ಪ್ರತ್ಯೇಕ ಸ್ಥಳದಲ್ಲಿ ತಂಗಿದ್ದರೆ ಅಥವಾ ನಿಮಗೆ ಖಚಿತವಿಲ್ಲದಿದ್ದರೆ, Hidden ಬಳಸಿ Go and Help ಬಳಸುವುದು ಸಂಪೂರ್ಣ ಸಹಜ.",
        "ಸೈನ್ ಇನ್ ಆಗದವರಿಗೆ ಸದಸ್ಯರ ನಿರ್ದೇಶಾಂಕಗಳನ್ನು ಎಂದಿಗೂ ನೀಡುವುದಿಲ್ಲ; ನಿಮ್ಮ ಫೋನ್ ಸಂಖ್ಯೆಯನ್ನೂ ಇತರ ಬಳಕೆದಾರರೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ. ಆದರೂ ನೀವು ಪ್ರಕಟಿಸಿದ ಪ್ರತಿಯೊಂದು ನಿರ್ದೇಶಾಂಕವನ್ನೂ ಶಾಶ್ವತವಾಗಿ ಸಾರ್ವಜನಿಕವಾಗಿದೆ ಎಂದು ಪರಿಗಣಿಸಿ: ಒಮ್ಮೆ ಯಾರಾದರೂ ನೋಡಿದರೆ ಅದನ್ನು ಹಿಂದಕ್ಕೆ ಪಡೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ.",
        "ಮೊದಲ ಬಾರಿಗೆ ಯಾರನ್ನಾದರೂ ಭೇಟಿಯಾಗುವಾಗ",
        "ಹಗಲಿನಲ್ಲಿ, ಇತರರು ನಿಮ್ಮನ್ನು ನೋಡಬಹುದಾದ ಸಾರ್ವಜನಿಕ ಸ್ಥಳದಲ್ಲಿ ಭೇಟಿಯಾಗಿ: ಚೌಕ, ನಿಲ್ದಾಣ, ಕೆಫೆ ಅಥವಾ ಅಂಗಡಿಯ ಪ್ರವೇಶದ್ವಾರ. ವಿನಂತಿ ಎಷ್ಟೇ ಸಮಂಜಸವಾಗಿ ಕೇಳಿಸಿದರೂ, ಮೊದಲ ಭೇಟಿಗೆ ಖಾಸಗಿ ಮನೆ, ಬೀಗ ಹಾಕಿದ ಅಂಗಳ, ದೋಣಿ, ನೆಲಮಾಳಿಗೆ, ಕಟ್ಟಡ ನಿರ್ಮಾಣ ಸ್ಥಳ ಅಥವಾ ನಿರ್ಜನ ರಸ್ತೆಗೆ ಹೋಗಬೇಡಿ.",
        "ನೀವು ಯಾರನ್ನು ಭೇಟಿಯಾಗುತ್ತಿದ್ದೀರಿ, ಕೆಲಸವೇನು, ಎಲ್ಲಿ ಮತ್ತು ಯಾವಾಗ ಹಿಂದಿರುಗುವಿರಿ ಎಂಬುದನ್ನು ನಂಬಿಕೆಯ ಸ್ನೇಹಿತ, ಸಂಬಂಧಿ ಅಥವಾ ಹಾಸ್ಟೆಲ್ ಸ್ವಾಗತ ಸಿಬ್ಬಂದಿಗೆ ತಿಳಿಸಿ. ಎದುರಿನವರ ಪ್ರೊಫೈಲ್ ಬಳಕೆದಾರ ಹೆಸರನ್ನು ಮತ್ತು ಸಂಭಾಷಣೆಯ ಸ್ಕ್ರೀನ್‌ಶಾಟ್ ಅನ್ನು ಅವರಿಗೆ ಕಳುಹಿಸಿ. ಕೆಲಸ ಮುಗಿದಾಗ ಸಂದೇಶ ಕಳುಹಿಸುವುದಾಗಿ ಒಪ್ಪಿಕೊಳ್ಳಿ.",
        "ಹೋಗುವ ಮತ್ತು ಹಿಂದಿರುಗುವ ಪ್ರಯಾಣವನ್ನು ನೀವೇ ಏರ್ಪಡಿಸಿ; ತಕ್ಷಣ ಹೊರಡಲು ಸಾಕಷ್ಟು ಹಣ ಅಥವಾ ಬ್ಯಾಟರಿ ಉಳಿಸಿಕೊಳ್ಳಿ. ಮನೆಗೆ ಮರಳಲು ಎದುರಿನವರ ಮೇಲೆ ಅವಲಂಬಿಸಬೇಡಿ; ನಿಮ್ಮ ಹಿಂದಿರುಗುವ ಏಕೈಕ ಮಾರ್ಗ ಅವರ ಕಾರು, ದೋಣಿ ಅಥವಾ ದಯೆಯಾಗಿರಬಾರದು. ತಲುಪುವ ಮೊದಲು ಹೇಗೆ ಹೊರಡಬೇಕೆಂದು ತಿಳಿದುಕೊಳ್ಳಿ.",
        "ನಿಮಗೆ ಆರಾಮವಾಗುವವರೆಗೆ ಸಂಭಾಷಣೆಯನ್ನು Go and Help ಒಳಗೇ ಇರಿಸಿ. ಯಾರಾದರೂ ನಿಮ್ಮನ್ನು ಆತುರದಲ್ಲಿ ಅಪ್ಲಿಕೇಶನ್‌ನಿಂದ ಹೊರಗೆ ಕರೆದೊಯ್ಯಲು ಪ್ರಯತ್ನಿಸಿದರೆ, ಒಬ್ಬರೇ ಬರಲು ಒತ್ತಾಯಿಸಿದರೆ, ಕೊನೆಯ ಕ್ಷಣದಲ್ಲಿ ಭೇಟಿಯ ಸ್ಥಳವನ್ನು ಹೆಚ್ಚು ನಿರ್ಜನ ಸ್ಥಳಕ್ಕೆ ಬದಲಿಸಿದರೆ ಅಥವಾ ಸಾರ್ವಜನಿಕವಾಗಿ ಕಾಣಿಸಿಕೊಳ್ಳಲು ನಿರಾಕರಿಸಿದರೆ, ಅದು ಮುಖ್ಯ ಎಚ್ಚರಿಕೆ. ನಿಲ್ಲಿಸಿ.",
        "ಯಾವುದೇ ಕ್ಷಣದಲ್ಲಿ, ಕಾರಣ ಹೇಳದೆ ಮತ್ತು ಕ್ಷಮೆ ಕೇಳದೆ, ನೀವು ರದ್ದುಮಾಡಬಹುದು, ಹೊರಡಬಹುದು ಅಥವಾ ನಿರಾಕರಿಸಬಹುದು. ಅಸೌಕರ್ಯವೆನಿಸುವುದೇ ಸಾಕಷ್ಟು ಕಾರಣ. ನಿಜವಾದ ನೆರೆಹೊರೆಯವರು ಅರ್ಥಮಾಡಿಕೊಳ್ಳುತ್ತಾರೆ; ಇದಕ್ಕಾಗಿ ನಿಮ್ಮನ್ನು ಶಿಕ್ಷಿಸುವವರು ಸುರಕ್ಷಿತ ವ್ಯಕ್ತಿಗಳಾಗಿರಲಿಲ್ಲ.",
        "ವಿಮರ್ಶೆಗಳನ್ನು ಓದಿ—ವಿಮರ್ಶಾತ್ಮಕವಾಗಿ ಓದಿ",
        "ಯಾವುದಕ್ಕೂ ಒಪ್ಪುವ ಮೊದಲು ಎದುರಿನವರ ಪ್ರೊಫೈಲ್ ತೆರೆದು, ಸಹಾಯಕರಾಗಿಯೂ ಸಹಾಯ ಕೇಳಿದವರಾಗಿಯೂ ಅವರು ಪಡೆದಿರುವ ವಿಮರ್ಶೆಗಳನ್ನು ಓದಿ. ನಕ್ಷತ್ರಗಳ ಸಂಖ್ಯೆಯನ್ನು ಮಾತ್ರವಲ್ಲ, ಜನರು ನಿಜವಾಗಿ ಬರೆದಿರುವುದನ್ನು ಗಮನಿಸಿ.",
        "ಕೆಟ್ಟ ವಿಮರ್ಶೆಗಳಿದ್ದರೆ ದೂರವಿರಿ. ಒತ್ತಾಯ, ತಡವಾಗಿ ಬರುವುದು, ಬೇಡದ ಪ್ರಸ್ತಾಪಗಳು, ಪಾವತಿಸದ ಅಥವಾ ಪಾಲಿಸದ ಭರವಸೆಗಳು, ಮದ್ಯಪಾನ, ಆಕ್ರಮಣಕಾರಿ ವರ್ತನೆ ಅಥವಾ ಅಪಾಯಕಾರಿ ಪರಿಸ್ಥಿತಿಗಳ ಬಗ್ಗೆ ಪದೇಪದೇ ಉಲ್ಲೇಖವಿದ್ದರೆ, ಅವು ಎಚ್ಚರಿಕೆಗಳೇ. ಒಂದು ಕೆಟ್ಟ ವಿಮರ್ಶೆ ತಪ್ಪು ತಿಳುವಳಿಕೆಯಾಗಿರಬಹುದು; ಪುನರಾವರ್ತಿತ ಮಾದರಿ ಹಾಗೆಯೇ ಇರುತ್ತದೆ.",
        "ಅನುಮಾನಾಸ್ಪದ ಹೊಗಳಿಕೆಯನ್ನೂ ಎಚ್ಚರಿಕೆಯಿಂದ ನೋಡಿ: ಹೊಸ ಖಾತೆಗೆ ಒಂದೇ ರೀತಿಯ ಹಲವು ಹೊಗಳಿಕೆಯ ವಿಮರ್ಶೆಗಳು, ಒಂದೇ ಧ್ವನಿಯಲ್ಲಿ ಬರೆದ ವಿಮರ್ಶೆಗಳು ಅಥವಾ ಸದಾ ಬದಲಾಗುವ ಕಥೆಯಿರುವ ಪ್ರೊಫೈಲ್. ಮೌಲ್ಯಮಾಪನಗಳನ್ನು ಕೃತಕವಾಗಿ ರೂಪಿಸಬಹುದು; ಖಾಲಿ ಪ್ರೊಫೈಲ್ ನಿಮಗೆ ಏನನ್ನೂ ತಿಳಿಸುವುದಿಲ್ಲ.",
        "ಸ್ಥಳಗಳಿಗೂ ಇದೇ ಅನ್ವಯಿಸುತ್ತದೆ. ನಿರ್ದಿಷ್ಟ ವಿಳಾಸ, ಸ್ಥಳ, ಬಾರ್ ಅಥವಾ ಕಾರ್ಯಾಗಾರ ಅಸುರಕ್ಷಿತವೆಂದು ಸದಸ್ಯರು ವರದಿ ಮಾಡಿದರೆ, ಅವರನ್ನು ನಂಬಿ ಬೇರೆ ಸ್ಥಳ ಆರಿಸಿ—ಇಲ್ಲದಿದ್ದರೆ ಸಂತೋಷದಿಂದ ಮಾಡುವ ಕೆಲಸಕ್ಕೂ ಅದೇ ನಿಯಮ.",
        "ಮೌಲ್ಯಮಾಪನಗಳು ಘಟನೆ ನಡೆದ ನಂತರ ಸಂಗ್ರಹಿಸಿದ ಅಭಿಪ್ರಾಯಗಳು. ಅವು ಹಿನ್ನೆಲೆ ಪರಿಶೀಲನೆ, ವಿಮಾ ಪಾಲಿಸಿ ಅಥವಾ ಯಾರ ವರ್ತನೆಯ ಕುರಿತ Go and Help ನ ಭರವಸೆಯಲ್ಲ.",
        "ನೀವು ನಿರಾಕರಿಸಬೇಕಾದ ಕೆಲಸಗಳು",
        "ಅಪಾಯಕಾರಿ ಸ್ಥಳಗಳಿಗೆ ಪ್ರವೇಶಿಸಬೇಡಿ: ಅಪೂರ್ಣ ಅಥವಾ ಪಾಳುಬಿದ್ದ ಕಟ್ಟಡಗಳು, ಮೇಲ್ಛಾವಣಿಗಳು, ಅಟ್ಟಣಿಗೆಗಳು, ನೀವು ಪರಿಶೀಲಿಸದ ಏಣಿಗಳು, ಕಂದಕಗಳು, ಟ್ಯಾಂಕ್‌ಗಳು, ಬಾವಿಗಳು, ಮುಚ್ಚಿದ ಅಥವಾ ಗಾಳಿಯಿಲ್ಲದ ಜಾಗಗಳು, ಪ್ರವಾಹದ ನೀರು ಅಥವಾ ನಿಮ್ಮಲ್ಲಿಲ್ಲದ ಸಾಧನ ಮತ್ತು ತರಬೇತಿ ಅಗತ್ಯವಿರುವ ಸ್ಥಳಗಳು.",
        "ನಿಮಗೆ ಅರ್ಹತೆ, ಪರವಾನಗಿ ಅಥವಾ ವಿಮೆ ಇಲ್ಲದ ಕೆಲಸವನ್ನು ಕೈಗೆತ್ತಿಕೊಳ್ಳಬೇಡಿ. ವಿದ್ಯುತ್ ಕೆಲಸ, ಅನಿಲ, ಮುಖ್ಯ ಕೊಳವೆಗಳಿಗೆ ಸಂಪರ್ಕಿಸುವ ಕೊಳಾಯಿ ಕೆಲಸ, ಕಟ್ಟಡದ ರಚನೆ ದುರಸ್ತಿ, ಮರ ಕಡಿಯುವುದು, ಇತರರ ವಾಹನ ಚಾಲನೆ, ಮಕ್ಕಳ ಆರೈಕೆ, ಪ್ರಾಣಿಗಳ ನಿರ್ವಹಣೆ, ದುರ್ಬಲ ವಯಸ್ಕರ ಆರೈಕೆ, ವೈದ್ಯಕೀಯ ಅಥವಾ ಔಷಧಿ ಸಂಬಂಧಿತ ಸಹಾಯ, ರಾಸಾಯನಿಕಗಳು ಅಥವಾ ವಿದ್ಯುತ್ ಉಪಕರಣಗಳ ಬಳಕೆ—ಇವೆಲ್ಲವೂ ನೈಜ ಕಾನೂನು ಮತ್ತು ದೈಹಿಕ ಅಪಾಯ ಹೊಂದಿವೆ. ಸಹಾಯಮಾಡುವ ಮನಸ್ಸು ಅರ್ಹತೆಯಲ್ಲ.",
        "ಕಾನೂನುಬಾಹಿರ, ಅಪ್ರಾಮಾಣಿಕ ಅಥವಾ ವಿಚಿತ್ರವಾದದ್ದನ್ನು ನಿರಾಕರಿಸಿ: ತಿಳಿಯದ ಪ್ಯಾಕೆಟ್‌ಗಳನ್ನು ಸಾಗಿಸುವುದು, ಗಡಿ ದಾಟಿಸಿ ವಸ್ತುಗಳನ್ನು ಒಯ್ಯುವುದು, ಬೇರೆಯವರ ನಗದು, ಕಾರ್ಡ್, ದಾಖಲೆ ಅಥವಾ ಕ್ರಿಪ್ಟೋವನ್ನು ನೋಡಿಕೊಳ್ಳುವುದು, ಹಣ ಸಂಗ್ರಹಿಸಿ ಕಳುಹಿಸುವುದು ಅಥವಾ ಸರಿಯಾಗಿ ವಿವರಿಸದ ‘ಸಣ್ಣ ಸಹಾಯ’ಗಳನ್ನು ಮಾಡುವುದು.",
        "ಕೆಲಸವೇನು, ಎಲ್ಲಿ, ಎಷ್ಟು ಹೊತ್ತು, ಇನ್ನಾರು ಇರುತ್ತಾರೆ ಮತ್ತು ಯಾವ ಸಾಧನಗಳಿವೆ ಎಂದು ನೇರವಾಗಿ ಕೇಳಿ. ಅಸ್ಪಷ್ಟ ಉತ್ತರವೇ ಒಂದು ಉತ್ತರ. ಸ್ಥಳಕ್ಕೆ ಬಂದಾಗ ನಿಜಸ್ಥಿತಿ ಒಪ್ಪಿಕೊಂಡದ್ದಕ್ಕಿಂತ ಭಿನ್ನವಾಗಿದ್ದರೆ ಹೊರಡಿ—ಅಪಾಯಕಾರಿ ಮಧ್ಯಾಹ್ನವನ್ನು ಕಳೆಯುವ ಬಾಧ್ಯತೆ ನಿಮಗಿಲ್ಲ.",
        "ಪರಿಸ್ಥಿತಿಗಳು ಬದಲಾದರೆ ನಿಲ್ಲಿಸಿ: ಹವಾಮಾನ, ಕತ್ತಲು, ಮದ್ಯ ಅಥವಾ ಮಾದಕ ವಸ್ತುಗಳು, ಹೆಚ್ಚುವರಿ ಜನರ ಆಗಮನ, ಅಥವಾ ವಿನಂತಿಗಿಂತ ದೊಡ್ಡದಾಗಿ ಮತ್ತು ಅಪಾಯಕಾರಿಯಾಗಿ ಕೆಲಸ ನಿಧಾನವಾಗಿ ಬದಲಾಗುವುದು.",
        "ತುರ್ತು ಪರಿಸ್ಥಿತಿಗಳು",
        "ತುರ್ತು ಪರಿಸ್ಥಿತಿಯಲ್ಲಿ ನಮ್ಮನ್ನು ಅಲ್ಲ, ಮೊದಲು ನಿಮ್ಮ ಸ್ಥಳೀಯ ತುರ್ತು ಸೇವೆಗಳನ್ನು ಸಂಪರ್ಕಿಸಿ. Go and Help ಗೆ ತುರ್ತು ಸಹಾಯವಾಣಿ ಇಲ್ಲ, ಭದ್ರತಾ ತಂಡವಿಲ್ಲ ಮತ್ತು ನಿಮ್ಮ ಪರವಾಗಿ ಯಾರನ್ನೂ ಸಂಪರ್ಕಿಸುವ ಮಾರ್ಗವಿಲ್ಲ. ಪೊಲೀಸರು, ಆಂಬ್ಯುಲೆನ್ಸ್ ಮತ್ತು ಅಗ್ನಿಶಾಮಕ ಸೇವೆಗಳಷ್ಟೇ ನಿಮ್ಮ ಬಳಿಗೆ ಬರಬಲ್ಲರು.",
        "ಅಗತ್ಯ ಬೀಳುವ ಮೊದಲು ನೀವು ಇರುವ ಸ್ಥಳದ ತುರ್ತು ಸಂಖ್ಯೆಯನ್ನು ತಿಳಿದುಕೊಳ್ಳಿ. 112 ಯುರೋಪಿಯನ್ ಒಕ್ಕೂಟದಾದ್ಯಂತ ಮತ್ತು ಇತರ ಹಲವು ದೇಶಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ; 999, 911, 000 ಮತ್ತು ಇತರ ಸಂಖ್ಯೆಗಳು ಬೇರೆಡೆ ಬಳಸಲಾಗುತ್ತವೆ. ಚಾರ್ಜ್ ಆದ ಫೋನ್ ಅಥವಾ ಡೇಟಾ ಸಂಪರ್ಕವಿಲ್ಲದಿದ್ದರೂ ನೋಡಬಹುದಾದಲ್ಲಿ ಅದನ್ನು ಬರೆದು ಇಡಿ.",
        "ನಿಮ್ಮ ಫೋನ್ ಚಾರ್ಜ್ ಆಗಿರಲಿ, ಆಫ್‌ಲೈನ್ ನಕ್ಷೆ ಅಥವಾ ವಿಳಾಸದ ಟಿಪ್ಪಣಿಗಳನ್ನು ಇಟ್ಟುಕೊಳ್ಳಿ, ನೀವು ತಂಗಿರುವ ಸ್ಥಳದ ಹೆಸರು ಮತ್ತು ಬೀದಿ ತಿಳಿದುಕೊಳ್ಳಿ, ಮತ್ತು ಪರ್ಸ್‌ನಿಂದ ಪ್ರತ್ಯೇಕವಾಗಿ ಸ್ವಲ್ಪ ತುರ್ತು ಹಣ ಇಟ್ಟುಕೊಳ್ಳಿ.",
        "ನಿಮಗೆ ಗಾಯವಾದರೆ, ಬೆದರಿಕೆ ಬಂದರೆ ಅಥವಾ ದರೋಡೆಗೊಳಗಾದರೆ ಸ್ಥಳೀಯ ಅಧಿಕಾರಿಗಳಿಗೆ ವರದಿ ಮಾಡಿ ಮತ್ತು ಉಲ್ಲೇಖ ಸಂಖ್ಯೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳಿ. ನಂತರ ಆ ಸದಸ್ಯರನ್ನೂ ನಮಗೆ ವರದಿ ಮಾಡಿ; ಆಗ ನಾವು ಅವರ ಖಾತೆಯ ಬಗ್ಗೆ ಕ್ರಮ ಕೈಗೊಳ್ಳಬಹುದು.",
        "ಕಿರುಕುಳ, ವರದಿ ಮಾಡುವುದು ಮತ್ತು ನಿರ್ಬಂಧಿಸುವುದು",
        "Go and Help ನಲ್ಲಿ ಯಾರೂ ಲೈಂಗಿಕ ಪ್ರಸ್ತಾಪಗಳು, ವರ್ಣದ್ವೇಷ, ಬೆದರಿಕೆ, ಅವಮಾನ, ಪದೇಪದೇ ಬೇಡದ ಸಂಪರ್ಕ, ಮದ್ಯಪಾನಕ್ಕೆ ಒತ್ತಡ, ಉಳಿಯಲು ಒತ್ತಾಯ ಅಥವಾ ಹಣ, ನಗ್ನ ಚಿತ್ರಗಳು ಅಥವಾ ವೈಯಕ್ತಿಕ ದಾಖಲೆಗಳ ಬೇಡಿಕೆಯನ್ನು ಸಹಿಸಬೇಕಾಗಿಲ್ಲ. ಇವುಗಳಲ್ಲಿ ಯಾವುದೂ ಸಹಾಯ ವಿನಂತಿಯ ಭಾಗವಾಗಿರಬಾರದು.",
        "ಉತ್ತರಿಸುವುದನ್ನು ನಿಲ್ಲಿಸಿ, ಸಾಕ್ಷ್ಯ ಉಳಿಸಿ, ಅವರ ಪ್ರೊಫೈಲ್ ಅಥವಾ ಸಂಭಾಷಣೆಯಿಂದ ಸದಸ್ಯರನ್ನು ವರದಿ ಮಾಡಿ. ಸ್ಕ್ರೀನ್‌ಶಾಟ್‌ಗಳು, ದಿನಾಂಕಗಳು ಮತ್ತು ನಿಖರ ಪದಗಳು ಸಾಮಾನ್ಯ ದೂರಿಗಿಂತ ನಮಗೆ ಹೆಚ್ಚು ಸಹಾಯ ಮಾಡುತ್ತವೆ. ವರದಿ ಮಾಡುವ ಮೊದಲು ಸಂಭಾಷಣೆಯನ್ನು ಅಳಿಸಬೇಡಿ.",
        "ನಿರ್ಬಂಧಿಸಿದರೆ ಆ ವ್ಯಕ್ತಿ ನಿಮ್ಮ ಸಂಭಾಷಣೆಗಳಿಂದ ದೂರವಾಗುತ್ತಾರೆ ಮತ್ತು ಮತ್ತೆ ನಿಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಲು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ. ವರದಿ ಮಾಡಿದರೆ ನಮಗೂ ತಿಳಿಯುತ್ತದೆ; ನಾವು ಖಾತೆಯನ್ನು ಪರಿಶೀಲಿಸಿ, ನಿರ್ಬಂಧಿಸಬಹುದು ಅಥವಾ Go and Help ನಿಂದ ಸಂಪೂರ್ಣವಾಗಿ ತೆಗೆದುಹಾಕಬಹುದು. ಯಾರಾದರೂ ನಿಮ್ಮನ್ನು ಭಯಪಡಿಸಿದರೆ ಎರಡನ್ನೂ ಮಾಡಿ.",
        "ಭಯಾನಕ ಘಟನೆ ಆಗದಿದ್ದರೂ ಕೆಟ್ಟ ಅನುಭವಗಳನ್ನು ವರದಿ ಮಾಡಿ—ಮುಂದಿನ ಪ್ರಯಾಣಿಕರನ್ನು ರಕ್ಷಿಸುವುದು ಇಂತಹ ತಪ್ಪಿಸಿಕೊಂಡ ಅಪಾಯಗಳೇ. ಪ್ರಾಮಾಣಿಕ ವಿಮರ್ಶೆಗಳನ್ನು ಬರೆಯಿರಿ: ಶಾಂತವಾದ, ವಾಸ್ತವಾಧಾರಿತ ವಿವರಣೆ ಕೋಪದ ಬರಹಕ್ಕಿಂತ ಹೆಚ್ಚು ಮೌಲ್ಯಯುತ.",
        "ನಿಮ್ಮ ಫೋನ್, ವಿಳಾಸ, ದಾಖಲೆಗಳು ಮತ್ತು ಹಣವನ್ನು ರಕ್ಷಿಸಿ",
        "ಅನ್‌ಲಾಕ್ ಮಾಡಿದ ಫೋನ್ ಅನ್ನು ಎಂದಿಗೂ ಯಾರಿಗೂ ಕೊಡಬೇಡಿ; ಪಾಸ್‌ವರ್ಡ್ ಅಥವಾ ದೃಢೀಕರಣ ಕೋಡ್‌ಗಳನ್ನು ಹಂಚಿಕೊಳ್ಳಬೇಡಿ; ನಿಮ್ಮ ಖಾತೆಗಳಲ್ಲಿ ‘ಒಂದು ಕ್ಷಣ ನೋಡಲಿ’ ಎಂದು ಯಾರಿಗೂ ಬಿಡಬೇಡಿ. ನಿಮ್ಮ ಫೋನ್‌ಗೆ ಬಂದ ಕೋಡ್ ಕೇಳುವವರು ನಿಮ್ಮಿಂದ ಏನನ್ನಾದರೂ ಕಸಿದುಕೊಳ್ಳಲು ಪ್ರಯತ್ನಿಸುತ್ತಿದ್ದಾರೆ.",
        "ಮನೆಯ ವಿಳಾಸ, ಹಾಸ್ಟೆಲ್ ಕೊಠಡಿ ಸಂಖ್ಯೆ, ಕೆಲಸದ ಸ್ಥಳ, ಪಾಸ್‌ಪೋರ್ಟ್, ವೀಸಾ, ಗುರುತಿನ ಚೀಟಿ ಮತ್ತು ಪ್ರಯಾಣದ ದಾಖಲೆಗಳನ್ನು ನಿಮ್ಮಲ್ಲೇ ಇಟ್ಟುಕೊಳ್ಳಿ. ಯಾರಿಗಾಗಿಯೂ ಅವುಗಳ ಫೋಟೋ ತೆಗೆದುಕೊಡಬೇಡಿ, ಭದ್ರತೆ ಅಥವಾ ಠೇವಣಿಯಾಗಿ ಬಿಡಬೇಡಿ, ಮತ್ತು ನೀವು ಕೆಲಸ ಮಾಡುವಾಗ ಯಾರಿಗೂ ಅವನ್ನು ಹಿಡಿಯಲು ಕೊಡಬೇಡಿ.",
        "ನಿಮ್ಮ ಫೋನ್ ಸಂಖ್ಯೆಯನ್ನು ಇತರ ಬಳಕೆದಾರರೊಂದಿಗೆ ಎಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ. ಅದು ನಿಮ್ಮ ಸ್ವಂತ ಖಾತೆಗಾಗಿ ಮಾತ್ರ ಇರಿಸಲಾಗುತ್ತದೆ; ಯಾವುದೇ ಸದಸ್ಯ ಅಥವಾ ಅತಿಥಿ ಅದನ್ನು ನೋಡಲಾರರು. ಯಾರಿಗಾದರೂ ಸಂಖ್ಯೆಯನ್ನು ನೀಡಲು ನೀವು ಬಯಸಿದರೆ, ನಿಮಗೆ ಆರಾಮವಿರುವಾಗ ನೀವೇ ನೀಡಿ.",
        "Go and Help ಕೆಲಸಕ್ಕಾಗಿ ಎಂದಿಗೂ ಹಣ ಕೇಳುವುದಿಲ್ಲ ಮತ್ತು ಪಾವತಿ ಸಂಗ್ರಹಿಸಲು ಅಪರಿಚಿತರನ್ನು ಕಳುಹಿಸುವುದಿಲ್ಲ. ಸದಸ್ಯರಿಗೆ ಠೇವಣಿ, ಉಡುಗೊರೆ ಕಾರ್ಡ್, ಕ್ರಿಪ್ಟೋ ಅಥವಾ ಬ್ಯಾಂಕ್ ವರ್ಗಾವಣೆ ಕಳುಹಿಸಬೇಡಿ; ಹೆಚ್ಚು ಹಣ ಪಡೆದು ಹಿಂದಿರುಗಿಸುವ ಒಪ್ಪಂದಗಳನ್ನು ಸ್ವೀಕರಿಸಬೇಡಿ; ಸ್ನೇಹಪರ ಸಂಭಾಷಣೆಯನ್ನು ನಿಮ್ಮ ಹಣಕಾಸು ಅಥವಾ ಪ್ರಣಯದ ಕಡೆಗೆ ತಿರುಗಿಸುವವರ ಬಗ್ಗೆ ಎಚ್ಚರದಿಂದಿರಿ.",
        "ಸದಸ್ಯತ್ವದ ಪಾವತಿಗಳನ್ನು Stripe ನಿರ್ವಹಿಸುತ್ತದೆ. ಸಂದೇಶದಲ್ಲಿ ನಿಮ್ಮ ಸಂಪೂರ್ಣ ಕಾರ್ಡ್ ಸಂಖ್ಯೆ, PIN ಅಥವಾ ಬ್ಯಾಂಕ್ ಪಾಸ್‌ವರ್ಡ್ ಅನ್ನು ನಾವು ಕೇಳುವುದಿಲ್ಲ; ನಮ್ಮ ಪರವಾಗಿ ಕೆಲಸಮಾಡುತ್ತೇವೆ ಎನ್ನುವವರೂ ಕೇಳಬಾರದು.",
        "ಗಡಿಗಳು, ಸ್ಥಳೀಯ ಕಾನೂನು ಮತ್ತು ಸ್ಥಳೀಯ ಸಂಪ್ರದಾಯ",
        "Go and Help ಅನ್ನು ವಿಶ್ವದಾದ್ಯಂತ ಬಳಸಲಾಗುತ್ತದೆ; ಒಂದು ದೇಶದಲ್ಲಿ ಸಹಜವೆನಿಸುವುದು ಪಕ್ಕದ ದೇಶದಲ್ಲಿ ಕಾನೂನುಬಾಹಿರವಾಗಿರಬಹುದು. ಹಣ ಅಥವಾ ಪ್ರತಿಫಲಕ್ಕಾಗಿ ಕೆಲಸ ಮಾಡುವುದು—ಆಹಾರ, ವಸತಿ ಅಥವಾ ಪ್ರವಾಸವೂ ಸೇರಿ—ಹಣ ಕೈಮಾರದೇ ಇದ್ದರೂ ವೀಸಾ ಅಥವಾ ವಲಸೆ ನಿಯಮಗಳನ್ನು ಉಲ್ಲಂಘಿಸಬಹುದು. ನಿಮ್ಮ ವೀಸಾ ಷರತ್ತುಗಳನ್ನು ಪರಿಶೀಲಿಸಿ; ಅದು ನಿಮ್ಮ ಹೊಣೆ, ನಮ್ಮದಲ್ಲ.",
        "ಸ್ಥಳೀಯ ಕಾನೂನನ್ನು ಗಂಭೀರವಾಗಿ ಪರಿಗಣಿಸಿ: ತೆರಿಗೆ ಮತ್ತು ವರದಿ ನಿಯಮಗಳು, ವಿಮಾ ಅವಶ್ಯಕತೆಗಳು, ವೃತ್ತಿ ಮತ್ತು ವಾಹನ ಚಾಲನಾ ಪರವಾನಗಿಗಳು, ಮದ್ಯ ಮತ್ತು ಮಾದಕ ವಸ್ತುಗಳ ಕಾನೂನು, ಛಾಯಾಚಿತ್ರ ನಿರ್ಬಂಧಗಳು, ಪ್ರತಿಭಟನೆ ಮತ್ತು ಕರ್ಫ್ಯೂ ನಿಯಮಗಳು, ಹಾಗೆಯೇ ಯಾರು ಕೆಲಸ ಮಾಡಬಹುದು ಎಂಬ ನಿಯಮಗಳು. ವಿದೇಶದಲ್ಲಿ ತಿಳಿದಿರಲಿಲ್ಲ ಎನ್ನುವುದು ಅಪರೂಪವಾಗಿ ಸಮರ್ಥನೆಯಾಗುತ್ತದೆ.",
        "ಸ್ಥಳೀಯ ಸಂಪ್ರದಾಯ ಮತ್ತು ಅಪಾಯಗಳನ್ನೂ ಗಮನಿಸಿ: ಕತ್ತಲಾದ ಬಳಿಕ ಸುರಕ್ಷಿತವಲ್ಲದ ನೆರೆಹೊರೆಗಳು, ಅನಗತ್ಯ ಗಮನ ಸೆಳೆಯುವ ಉಡುಗೆ ಅಥವಾ ವರ್ತನೆ, ನೀರು ಮತ್ತು ಆಹಾರದ ಸುರಕ್ಷತೆ, ಪ್ರಾಣಿಗಳು ಹಾಗೂ ಬಿಸಿಲು, ಬಿರುಗಾಳಿ ಅಥವಾ ಪ್ರವಾಹದಂತಹ ಋತುಮಾನ ಅಪಾಯಗಳು.",
        "ಕೆಲಸಕ್ಕಾಗಿ ಗಡಿ ದಾಟುವುದು ವಿಶೇಷ ಎಚ್ಚರಿಕೆ ಬೇಡುತ್ತದೆ: ಯಾರಿಗಾಗಿಯೂ ಏನನ್ನೂ ಸಾಗಿಸಬೇಡಿ, ನಿಮ್ಮ ದಾಖಲೆಗಳನ್ನು ನಿಮ್ಮ ಬಳಿಯೇ ಇಟ್ಟುಕೊಳ್ಳಿ ಮತ್ತು ಹಿಂದಿರುಗಲು ಸಾಧ್ಯವಿದೆಯೆಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
        "Go and Help ಮಾಡದಿರುವುದು",
        "ನಾವು ಭೇಟಿಗಳನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡುವುದಿಲ್ಲ, ಹಾಜರಾಗುವುದಿಲ್ಲ ಅಥವಾ ನಿಗಾ ವಹಿಸುವುದಿಲ್ಲ. ನಿಮ್ಮ ಏರ್ಪಾಟಿನ ಹಿಂದೆ ಬೆಂಗಾವಲು, ಜೊತೆಗಾರ, ವೀಕ್ಷಕ ಅಥವಾ ವಿಮೆ ಯಾವುದೂ ಇಲ್ಲ. ವಯಸ್ಕರು ಏರ್ಪಡಿಸುತ್ತಾರೆ, ವಯಸ್ಕರು ನೆರವೇರಿಸುತ್ತಾರೆ ಮತ್ತು ವಯಸ್ಕರೇ ಅಪಾಯವನ್ನು ಹೊರುತ್ತಾರೆ.",
        "Go and Help ನಲ್ಲಿನ ಪರಿಶೀಲಿತ ಗುರುತು ಎಂದರೆ ಸದಸ್ಯರು ತಮ್ಮ ಇಮೇಲ್ ವಿಳಾಸವನ್ನು ದೃಢಪಡಿಸಿದ್ದಾರೆ ಅಷ್ಟೇ. ಅದು ಗುರುತು ಪರಿಶೀಲನೆ, ಅಪರಾಧ ದಾಖಲೆ ಪರಿಶೀಲನೆ, ಅರ್ಹತಾ ಪರಿಶೀಲನೆ ಅಥವಾ ವ್ಯಕ್ತಿತ್ವದ ಶಿಫಾರಸು ಯಾವುದೂ ಅಲ್ಲ.",
        "ನಕ್ಷತ್ರ ಮೌಲ್ಯಮಾಪನಗಳು, ದಯಾಳುತನದ ಅಂಕಗಳು ಮತ್ತು ಸಹಾಯಕ ವಿಮರ್ಶೆಗಳು ಹಿಂದೆ ಏನಾಯಿತು ಎಂಬುದನ್ನು ವಿವರಿಸುತ್ತವೆ. ಮುಂದಿನ ಬಾರಿ ಯಾರಾದರೂ ಏನು ಮಾಡುತ್ತಾರೆಂದು ಅವು ಊಹಿಸಲಾರವು; ಭೇಟಿಯು ಸುರಕ್ಷಿತವಾಗಿರುತ್ತದೆ ಎಂಬ Go and Help ನ ಭರವಸೆಯೂ ಅಲ್ಲ.",
        "ಸಂದೇಶದಲ್ಲಿ, ಭೇಟಿಯ ಸ್ಥಳದಲ್ಲಿ ಅಥವಾ ತಲುಪಿದಾಗ ಏನಾದರೂ ತಪ್ಪಾಗಿದೆ ಎನಿಸಿದರೆ, ಆ ಭಾವನೆಯನ್ನು ನಂಬಿ, ಅಲ್ಲಿಂದ ಹೊರಟು ನಮಗೆ ತಿಳಿಸಿ. ಯಾವುದೇ ಕೆಲಸ, ಉಪಕಾರ, ಊಟ ಅಥವಾ ವಸತಿ ನಿಮ್ಮ ಸುರಕ್ಷತೆಗಿಂತ ಮುಖ್ಯವಲ್ಲ.",
    ),
}
